sp_theme.css_variables:
/* ============================================================
   ANNOUNCEMENT EXPERIENCE SUITE
   AES Theme — Charcoal + Lime
   ============================================================ */


/* ------------------------------------------------------------
   AES PALETTE
   ------------------------------------------------------------ */

$aes-charcoal: #2A2D2F;
$aes-dark: #121212;

$aes-deep-forest: #153126;
$aes-pine: #2E5A44;
$aes-sage: #9BC17A;

$aes-lime: #CFFF04;
$aes-lime-hover: #B8E600;
$aes-lime-soft: #EFFF9A;

$aes-warm: #F4F1EA;
$aes-cool-gray: #D8DDE0;


/* ------------------------------------------------------------
   TEXT
   ------------------------------------------------------------ */

$text-primary: #2A2D2F;
$text-secondary: #4F5C62;
$text-tertiary: #616D74;
$text-white: #FFFFFF;

$text-color: $text-primary;
$text-muted: $text-tertiary;


/* ------------------------------------------------------------
   BACKGROUNDS
   ------------------------------------------------------------ */

$background-primary: #FFFFFF;
$background-secondary: #F4F1EA;
$background-tertiary: #E7E9E8;

$body-bg: $background-secondary;
$sp-body-bg: $background-secondary;


/* ------------------------------------------------------------
   BRAND
   ------------------------------------------------------------ */

$brand-primary: $aes-charcoal;

$brand-primary-darkest: $aes-dark;
$brand-primary-darker: $aes-deep-forest;
$brand-primary-lighter: $aes-sage;
$brand-primary-lightest: #EAF4DC;

$primary: $brand-primary;


/* ------------------------------------------------------------
   AES ACCENT
   Lime is an accent, NOT a generic semantic state.
   ------------------------------------------------------------ */

$aes-accent: $aes-lime;
$aes-accent-hover: $aes-lime-hover;
$aes-accent-soft: $aes-lime-soft;
$aes-accent-text: $aes-deep-forest;


/* ------------------------------------------------------------
   BORDERS
   ------------------------------------------------------------ */

$border-primary: #4F5C62;
$border-secondary: #859095;
$border-tertiary: $aes-cool-gray;

$hr-border: $border-tertiary;


/* ------------------------------------------------------------
   LINKS
   ------------------------------------------------------------ */

$link-color: $aes-pine;
$link-hover-color: $aes-deep-forest;


/* ------------------------------------------------------------
   NAVBAR
   ------------------------------------------------------------ */

$navbar-inverse-bg: $aes-charcoal;
$navbar-inverse-border: $aes-dark;

$navbar-inverse-color: $aes-warm;

$navbar-inverse-link-color: $aes-warm;
$navbar-inverse-link-hover-color: $aes-lime;
$navbar-inverse-link-hover-bg: transparent;

$navbar-inverse-link-active-color: $aes-lime;
$navbar-inverse-link-active-bg: #202324;

$navbar-inverse-link-disabled-color: #859095;
$navbar-inverse-link-disabled-bg: transparent;

$navbar-inverse-brand-color: $aes-warm;
$navbar-inverse-brand-hover-color: $aes-lime;

$sp-navbar-inverse-bg: $aes-charcoal;
$sp-navbar-divider-color: #3B3F41;


/* ------------------------------------------------------------
   ACTIVE / SELECTED
   ------------------------------------------------------------ */

$select-primary: $aes-pine;
$select-primary-lighter: #EAF4DC;
$select-primary-darker: $aes-deep-forest;

$component-active-color: $aes-deep-forest;
$component-active-bg: $aes-lime;


/* ------------------------------------------------------------
   INPUTS
   ------------------------------------------------------------ */

$input-bg: #FFFFFF;
$input-bg-disabled: $background-secondary;

$input-color: $text-primary;
$input-border: #859095;
$input-border-focus: $aes-pine;

$input-color-placeholder: $text-tertiary;

$input-group-addon-bg: $background-secondary;
$input-group-addon-border-color: $input-border;


/* ------------------------------------------------------------
   BUTTONS
   ------------------------------------------------------------ */

$btn-font-weight: 600;

$btn-default-color: $text-primary;
$btn-default-bg: #FFFFFF;
$btn-default-border: #859095;

$btn-primary-color: #FFFFFF;
$btn-primary-bg: $aes-charcoal;
$btn-primary-border: $aes-charcoal;


/* ------------------------------------------------------------
   PANELS / CARDS
   ------------------------------------------------------------ */

$panel-bg: #FFFFFF;

$panel-inner-border: $border-tertiary;
$panel-footer-bg: $background-secondary;

$panel-default-text: $text-primary;
$panel-default-border: $border-tertiary;
$panel-default-heading-bg: $background-secondary;


/* ------------------------------------------------------------
   DROPDOWNS
   ------------------------------------------------------------ */

$dropdown-bg: #FFFFFF;

$dropdown-border: $border-tertiary;
$dropdown-fallback-border: $border-tertiary;
$dropdown-divider-bg: $border-tertiary;

$dropdown-link-color: $text-primary;

$dropdown-link-hover-color: $text-primary;
$dropdown-link-hover-bg: #EAF4DC;

$dropdown-link-active-color: $aes-deep-forest;
$dropdown-link-active-bg: $aes-lime;

$dropdown-link-disabled-color: $text-muted;
$dropdown-header-color: $text-muted;


/* ------------------------------------------------------------
   TABS
   ------------------------------------------------------------ */

$nav-tabs-border-color: $border-tertiary;

$nav-tabs-active-link-hover-bg: transparent;
$nav-tabs-active-link-hover-color: $aes-pine;
$nav-tabs-active-link-hover-border-color: $aes-pine;

$nav-tabs-justified-active-link-border-color: $aes-pine;

$nav-pills-active-link-hover-bg: $aes-pine;
$nav-pills-active-link-hover-color: #FFFFFF;


/* ------------------------------------------------------------
   PAGINATION
   ------------------------------------------------------------ */

$pagination-color: $link-color;
$pagination-bg: #FFFFFF;
$pagination-border: $border-tertiary;

$pagination-hover-color: $link-hover-color;
$pagination-hover-bg: $background-secondary;
$pagination-hover-border: $border-secondary;

$pagination-active-color: $aes-deep-forest;
$pagination-active-bg: $aes-lime;
$pagination-active-border: $aes-lime;

$pagination-disabled-color: $text-muted;
$pagination-disabled-bg: #FFFFFF;
$pagination-disabled-border: $border-tertiary;


/* ------------------------------------------------------------
   TABLES
   ------------------------------------------------------------ */

$table-bg: transparent;
$table-bg-accent: $background-secondary;
$table-bg-hover: #EAF4DC;
$table-border-color: $border-tertiary;


/* ------------------------------------------------------------
   LIST GROUPS
   ------------------------------------------------------------ */

$list-group-bg: #FFFFFF;
$list-group-border: $border-tertiary;
$list-group-hover-bg: $background-secondary;

$list-group-active-color: $aes-deep-forest;
$list-group-active-bg: $aes-lime;
$list-group-active-border: $aes-lime;

$list-group-disabled-color: $text-tertiary;
$list-group-disabled-bg: $background-secondary;

$list-group-link-color: $text-primary;
$list-group-link-hover-color: $text-primary;
$list-group-link-heading-color: $text-primary;


/* ------------------------------------------------------------
   MODALS / POPOVERS
   ------------------------------------------------------------ */

$modal-content-bg: #FFFFFF;
$modal-content-border-color: $border-tertiary;
$modal-content-fallback-border-color: $border-tertiary;

$modal-backdrop-bg: $aes-dark;

$popover-bg: #FFFFFF;
$popover-border-color: $border-tertiary;
$popover-fallback-border-color: $border-tertiary;
$popover-title-bg: $background-secondary;


/* ------------------------------------------------------------
   BADGES
   ------------------------------------------------------------ */

$badge-color: #FFFFFF;
$badge-bg: #4F5C62;

$badge-active-color: $aes-deep-forest;
$badge-active-bg: $aes-lime;


/* ------------------------------------------------------------
   AES HEADER
   ------------------------------------------------------------ */

$aes-header-text-color: $aes-warm;
$aes-header-secondary-text-color: $aes-cool-gray;


/* ------------------------------------------------------------
   AES SEMANTIC TOKENS
   Do not derive semantic states from company branding.
   ------------------------------------------------------------ */

$aes-urgent-tag-color: #B31B2C;
$aes-urgent-tag-bg: #F9C8CE;
$aes-urgent-tag-border: #E52239;


/* ============================================================
   AES DESIGN TOKENS
   ============================================================ */

/* Spacing */
$aes-space-xs: 4px;
$aes-space-sm: 8px;
$aes-space-md: 12px;
$aes-space-lg: 16px;
$aes-space-xl: 24px;
$aes-space-2xl: 32px;
$aes-space-3xl: 40px;

/* Radius */
$aes-radius-sm: 4px;
$aes-radius-md: 8px;
$aes-radius-lg: 12px;

/* Shadows */
$aes-shadow-sm: 0 1px 3px rgba(18, 18, 18, 0.08);
$aes-shadow-md: 0 4px 12px rgba(18, 18, 18, 0.10);

/* Content */
$aes-content-max-width: 1440px;

/* Transitions */
$aes-transition-fast: 150ms ease;
$aes-transition-base: 200ms ease;

/* ============================================================
   TYPOGRAPHY
   ============================================================ */

$font-family-sans-serif: "Lato", Arial, sans-serif;
$font-family-base: $font-family-sans-serif;

$font-size-base: 16px;
$font-size-small: 14px;
$font-size-large: 18px;

$font-size-h1: 36px;
$font-size-h2: 30px;
$font-size-h3: 24px;
$font-size-h4: 20px;
$font-size-h5: 18px;
$font-size-h6: 16px;

$line-height-base: 1.5;
$headings-line-height: 1.2;

$headings-font-family: $font-family-base;
$headings-font-weight: 600;
$headings-color: $text-primary;

/* ============================================================
   AES - HEADER TOKENS
   ============================================================ */

/* AES Header */

$aes-header-title-size: 48px;
$aes-header-title-weight: 600;

$aes-header-subtitle-size: 18px;
$aes-header-subtitle-style: italic;

$aes-header-padding-x: 80px;
$aes-header-padding-y: 52px;

$aes-header-heading-gap: 8px;
$aes-header-search-gap: 72px;

$aes-header-logo-size: 56px;
$aes-header-logo-gap: 34px;

$aes-header-content-width: 1080px;
$aes-header-search-width: 896px;

$aes-radius-sm: 6px;
$aes-radius-md: 8px;
$aes-radius-lg: 12px;


$aes-content-max-width: 1600px;
$aes-page-gutter: 32px;

$aes-control-selected-bg: $text-primary;
$aes-control-active-bg: $text-primary;

$aes-urgent-background: #892116;
$aes-urgent-color: #FFFFFF;

$aes-new-background: #CFFF04;
$aes-new-color: #2A2D2F;

$aes-saved-color: #2E5A44;
